import {paperToyStability} from './paper-toy-stability-results.mjs';
import {convexHull3D,minimumVolumeEnclosingEllipsoid3D} from './geometry3d.mjs';
import {rotateLatent,orientLatentProjection} from './spatial-lab.mjs';

export function createStabilityLab(){
  const $=id=>document.getElementById(id);
  let showGeometry=true,showHull=true,showMvee=true,showPoints=true,showFlow=false,yaw=.5,pitch=.25;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const reps=()=>paperToyStability.representatives??[];
  function controls(){return `<div class="rp-controls panel"><label><input id="st-geometry" type="checkbox" ${showGeometry?'checked':''}> 坐标轴</label><label><input id="st-hull" type="checkbox" ${showHull?'checked':''}> 凸包</label><label><input id="st-mvee" type="checkbox" ${showMvee?'checked':''}> MVEE 包围椭球</label><label><input id="st-points" type="checkbox" ${showPoints?'checked':''}> 细胞点</label><label><input id="st-flow" type="checkbox" ${showFlow?'checked':''}> 固定顺序流线</label><button id="st-reset">复位视角</button></div>`;}
  function template(route='replicas'){const home=route==='replicas';return `<div class="rp-page"><div class="page-intro"><p class="eyebrow">REGVELO · 20 次稳定性实验</p><h1>${home?'五组经典潜空间几何':'20 次训练的稳定性比较'}</h1><p>${home?'从 20 次独立拟合中选出五组几何代表，作为首页的主要观察对象。':'完整运行 20 次独立拟合，再按细胞两两距离结构聚类；表格列出全部运行，图中展示五个几何中心模型。'}</p></div><p id="st-status" class="panel rp-status" role="status"></p>${controls()}<div id="st-grid" class="stability-grid">${reps().length?reps().map((m,i)=>`<article class="panel stability-card"><div class="rp-row-label"><b>代表组 ${i+1}</b><span>第 ${m.stabilityRun??'—'} 次 · seed ${m.stabilitySeed??m.seed??'—'} · 训练 ${m.epochs??'—'} 轮 / 最佳验证轮 ${m.bestEpoch??'—'}</span></div><canvas id="st-chart-${i}" width="560" height="360" tabindex="0" aria-label="代表组 ${i+1} 的三维潜空间几何"></canvas><p>该模型来自 20 次实验的几何聚类中心。坐标系允许旋转，比较重点是点间距离、凸包和包围椭球。</p></article>`).join(''):'<section class="panel"><h2>20 次实验尚未完成</h2><p>训练结果写入 stability-runs 后，这里会自动显示 5 个几何代表组。</p></section>'}</div>${home?'':summaryTable()}</div>`;}
  function summaryTable(){const rows=(paperToyStability.summaries??[]).map(item=>`<tr><td>${item.run}</td><td>${item.seed}</td><td>${item.epochs??'—'}</td><td>${item.bestEpoch??'—'}</td><td>${item.status}</td></tr>`).join('');return `<section class="panel"><h2>20 次运行记录</h2><div class="table-scroll"><table><thead><tr><th>运行</th><th>随机种子</th><th>训练轮数</th><th>最佳验证轮</th><th>状态</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;}
  function canvas(id){const c=$(id);if(!c)return null;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#f7fafc';ctx.fillRect(0,0,w,h);return {ctx,w,h};}
  function drawOne(model,i){const p=canvas(`st-chart-${i}`);if(!p)return;const {ctx,w,h}=p,mu=model.mu,geometry=convexHull3D(mu),mvee=minimumVolumeEnclosingEllipsoid3D(mu),points=[...mu],span=Math.max(1,...points.flat().map(Math.abs),...mvee.center.map((v,j)=>Math.abs(v)+mvee.extent[j])),scale=Math.min(w,h)*.36/span,frame=orientLatentProjection(mu[0],model.variance?.[0]??[1,1,1],yaw,pitch),to=v=>{const r=rotateLatent(v,yaw,pitch),q=frame.rotate(r);return [w/2+q[0]*scale,h/2-q[1]*scale,r[2]]};
    ctx.font='12px sans-serif';if(showGeometry)for(let j=0;j<3;j++){const v=[0,0,0];v[j]=span;const q=to(v);ctx.strokeStyle='#bcc8d5';ctx.beginPath();ctx.moveTo(w/2,h/2);ctx.lineTo(q[0],q[1]);ctx.stroke();ctx.fillStyle='#53667b';ctx.fillText(`z${j+1}`,q[0],q[1]);}
    const project=to,triangles=geometry.faces.map(face=>face.map(index=>project(mu[index]))).sort((a,b)=>a.reduce((s,v)=>s+v[2],0)-b.reduce((s,v)=>s+v[2],0));if(showHull){ctx.save();ctx.fillStyle='rgba(20,143,143,.13)';for(const tri of triangles){ctx.beginPath();ctx.moveTo(tri[0][0],tri[0][1]);ctx.lineTo(tri[1][0],tri[1][1]);ctx.lineTo(tri[2][0],tri[2][1]);ctx.closePath();ctx.fill();}ctx.strokeStyle='rgba(14,111,119,.65)';for(const [a,b] of geometry.edges){const p=project(mu[a]),q=project(mu[b]);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();}ctx.restore();}
    if(showMvee){const point=(lat,lon)=>mvee.center.map((v,j)=>v+mvee.vectors[j].reduce((sum,axis,k)=>sum+axis*(k===0?mvee.axes[0]*Math.cos(lat)*Math.cos(lon):k===1?mvee.axes[1]*Math.cos(lat)*Math.sin(lon):mvee.axes[2]*Math.sin(lat)),0));ctx.save();ctx.strokeStyle='rgba(92,77,162,.58)';for(const lat of [-Math.PI/4,0,Math.PI/4]){ctx.beginPath();for(let k=0;k<=32;k++){const q=project(point(lat,k*Math.PI/16));k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]);}ctx.stroke();}for(let k=0;k<6;k++){ctx.beginPath();for(let j=0;j<=24;j++){const q=project(point(-Math.PI/2+j*Math.PI/24,k*Math.PI/6));j?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]);}ctx.stroke();}ctx.restore();}
    if(showPoints)mu.forEach((v,k)=>{const q=project(v);ctx.fillStyle=k===0?'#9a4d9d':'#1568a0';ctx.beginPath();ctx.arc(q[0],q[1],k===0?4:2.5,0,Math.PI*2);ctx.fill();});
    if(showFlow){const order=mu.map((v,index)=>({index,v})).sort((a,b)=>b.v[0]-a.v[0]||b.v[1]-a.v[1]||b.v[2]-a.v[2]);ctx.save();ctx.strokeStyle='#cc6c33';ctx.setLineDash([5,4]);ctx.beginPath();order.forEach((item,k)=>{const q=project(item.v);k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]);});ctx.stroke();ctx.restore();}
  }
  function draw(){reps().forEach(drawOne);const p=$('st-status');if(p)p.textContent=paperToyStability.status==='complete'?`20 次独立拟合已完成，页面展示 ${reps().length} 个几何代表组。`:'20 次独立拟合正在运行或尚未导入。';}
  function setup(){for(const [id,key] of [['st-geometry','geometry'],['st-hull','hull'],['st-mvee','mvee'],['st-points','points'],['st-flow','flow']])$(id).onchange=()=>{if(key==='geometry')showGeometry=$(id).checked;if(key==='hull')showHull=$(id).checked;if(key==='mvee')showMvee=$(id).checked;if(key==='points')showPoints=$(id).checked;if(key==='flow')showFlow=$(id).checked;draw();};$('st-reset').onclick=()=>{yaw=.5;pitch=.25;draw();};const grid=$('st-grid');grid?.addEventListener?.('keydown',event=>{if(event.key==='ArrowLeft')yaw-=.1;if(event.key==='ArrowRight')yaw+=.1;if(event.key==='ArrowUp')pitch-=.1;if(event.key==='ArrowDown')pitch+=.1;draw();});grid?.querySelectorAll?.('canvas').forEach(canvas=>{let pointer=null;canvas.onpointerdown=event=>{pointer={x:event.clientX,y:event.clientY};canvas.setPointerCapture?.(event.pointerId);};canvas.onpointermove=event=>{if(!pointer)return;yaw+=(event.clientX-pointer.x)*.0035;pitch=Math.max(-1.4,Math.min(1.4,pitch+(event.clientY-pointer.y)*.0035));pointer={x:event.clientX,y:event.clientY};draw();};canvas.onpointerup=canvas.onpointercancel=()=>{pointer=null;};});draw();}
  return {template,setup,stop(){},refresh:draw,state:()=>({representatives:reps(),showGeometry,showHull,showMvee,showPoints,showFlow,yaw,pitch})};
}
